// Tests for data/fixed_relics.json — the guaranteed (fixed-effect) relics
// generated by prepare_fixed_relics.mjs from EquipParamAntique.csv. Checks the
// relic list, grouping, DLC tagging and effect resolution against values
// confirmed in the design spec (docs/superpowers/specs/2026-10-23-guaranteed-relics-design.md).
import { readFileSync } from 'fs';

let passed = 0, failed = 0;
function check(label, ok) {
  if (ok) { passed++; }
  else { failed++; console.error('  FAIL ' + label); }
}

const data = JSON.parse(readFileSync(new URL('../data/fixed_relics.json', import.meta.url), 'utf8'));
const relics = data.relics;
const byId = new Map(relics.map(r => [r.id, r]));
const names = id => (byId.get(id)?.effects || []).map(e => e.name);

check('exactly 84 guaranteed relics', relics.length === 84);
check('groups are listed in dropdown order', JSON.stringify(data.groups) === JSON.stringify(['boss', 'remembrance', 'signboard', 'misc']));
const groupCount = g => relics.filter(r => r.group === g).length;
check('18 boss relics', groupCount('boss') === 18);
check('24 remembrance relics', groupCount('remembrance') === 24);
check('39 Collector Signboard relics', groupCount('signboard') === 39);
check('3 misc relics', groupCount('misc') === 3);
check('relic ids are unique', byId.size === relics.length);

const EXPECTED_DLC = [2070, 2071, 2080, 19000, 19001, 19050, 19051,
  1600, 1610, 1620, 1630, 1640, 1650, 1660, 1670, 1680, 1690, 1700, 1710, 1720, 1730, 1740, 1750,
  1800, 1820, 1830, 1850, 1860, 1870, 1880, 1890, 1900, 1920];
const dlcIds = relics.filter(r => r.dlc).map(r => r.id).sort((a, b) => a - b);
check('DLC relics are exactly the 33 from the DLC name file', JSON.stringify(dlcIds) === JSON.stringify([...EXPECTED_DLC].sort((a, b) => a - b)));
check('Night of the Lord (2100) is base game', byId.get(2100) && !byId.get(2100).dlc);
check('dlc flag is only ever present as true', relics.every(r => r.dlc === undefined || r.dlc === true));

check('Night of the Lord effects resolve in game order', JSON.stringify(names(2100)) === JSON.stringify([
  'Switching Weapons Adds an Affinity Attack',
  'Boosts Attack Power of Added Affinity Attacks',
  'Switching Weapons Boosts Attack Power',
]));
const darkBeastTaking = byId.get(2001)?.effects.find(e => e.name === 'Taking attacks improves attack power');
check('Dark Night of the Beast internal id 100000 resolves to "Taking attacks improves attack power"', !!darkBeastTaking);
check('…and carries that effect\'s special classification', darkBeastTaking?.mul?.special === true);
const glass = byId.get(19051)?.effects.find(e => e.name === 'Successive Attacks Boost Attack Power');
check('Glass Necklace carries the stepped successive-attack effect', glass?.mul?.stepValues?.length === 3);
check('Starlight Shards relic (1520) has 3 Starlight Shards effects',
  names(1520).length === 3 && names(1520).every(n => n === 'Starlight Shards in possession at start of expedition'));
const evergaol = byId.get(1510)?.effects.find(e => e.name === 'Attack power increased for each evergaol prisoner defeated');
check('Signboard 1510 carries the counted Evergaol effect', evergaol?.mul?.variableCount === true);
check('effect names keep the game file\'s line breaks, like the pool data',
  names(2040).includes('Huge rune discount for shop purchases while on\nexpedition'));
check('…and still pick up mul/desc via the normalised name',
  !!byId.get(2040).effects.find(e => e.name.startsWith('Huge rune discount'))?.desc);

check('every relic has at least one effect', relics.every(r => r.effects.length > 0));
check('every effect name resolved (no "?" placeholders)', relics.every(r => r.effects.every(e => !e.name.startsWith('?'))));
check('every relic has a name', relics.every(r => typeof r.name === 'string' && r.name.length > 0));

const EXCLUDED = [...Array.from({ length: 32 }, (_, i) => 1000 + i * 10), 11003, 11004, 12004, 12005, 12006, 12007];
check('Small Jar Bazaar relics and +1 quest pickups are excluded', EXCLUDED.every(id => !byId.has(id)));

// index.html embeds this JSON as FIXED_RELICS (README embed script) — the
// embedded copy must match the generated file, or the page silently ships
// stale relic data.
{
  const html = readFileSync(new URL('../index.html', import.meta.url), 'utf8');
  const m = html.match(/const FIXED_RELICS = (\{.*?\});\n/s);
  check('index.html embeds FIXED_RELICS', !!m);
  check('embedded FIXED_RELICS matches data/fixed_relics.json',
    !!m && JSON.stringify(JSON.parse(m[1])) === JSON.stringify(data));
}

console.log(`\n${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
